using System.Collections.Generic;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurifyGainStatusDieAction", menuName = "Data/Battle/Battle Actions/Moonie/PurifyGainStatusDie Action")]
public class PurifyGainStatusDieAction : BattleAction
{
	[Header("Purify Gain Status Die Action")]
	[SerializeField]
	private HexAction hexAction;

	[SerializeField]
	[HideIf("multiplePurifyAction")]
	private PurifyAction purifyAction;

	[SerializeField]
	private bool multiplePurifyAction;

	[SerializeField]
	[ShowIf("multiplePurifyAction")]
	private PurifiedLightningAction purifiedLightningAction;

	public HexAction HexAction => hexAction;

	public PurifyAction PurifyAction => purifyAction;

	public bool MultiplePurifyAction => multiplePurifyAction;

	public PurifiedLightningAction PurifiedLightningAction => purifiedLightningAction;

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		if (multiplePurifyAction)
		{
			purifiedLightningAction.AreaCastTargetAmount(targets, amount, source);
		}
		else
		{
			purifyAction.AreaCastTargetAmount(targets, amount, source);
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
		{
			hexAction.Cast(source);
		});
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (multiplePurifyAction)
		{
			purifiedLightningAction.CastTargetAmount(target, amount, source);
		}
		else
		{
			purifyAction.CastTargetAmount(target, amount, source);
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
		{
			hexAction.Cast(source);
		});
	}
}
